// src/components/Navbar.js
// Navigation bar — shows an "Admin Panel" link if the logged-in user is admin.

import React from "react";
import { Link, useNavigate } from "react-router-dom";

function Navbar() {
  const navigate = useNavigate();

  const isLoggedIn = !!localStorage.getItem("token");

  // Parse user object stored after login (contains isAdmin flag)
  const user = JSON.parse(localStorage.getItem("user") || "{}");

  const handleLogout = () => {
    localStorage.removeItem("token");
    localStorage.removeItem("user"); // Clear user info on logout too
    navigate("/login");
  };

  return (
    <nav>
      <Link to="/" style={{ fontWeight: "bold", fontSize: "17px" }}>
        🔍 Lost &amp; Found
      </Link>

      <Link to="/">Home</Link>
      <Link to="/create">Post Item</Link>

      {/* Show Admin Panel link only for admin users */}
      {isLoggedIn && user.isAdmin && (
        <Link
          to="/admin"
          style={{
            background: "#e74c3c",
            padding: "4px 10px",
            borderRadius: "4px",
            color: "white",
            fontWeight: "bold",
          }}
        >
          🛠️ Admin Panel
        </Link>
      )}

      {isLoggedIn ? (
        <button
          onClick={handleLogout}
          style={{
            background: "none",
            border: "1px solid white",
            color: "white",
            padding: "4px 10px",
            cursor: "pointer",
            borderRadius: "4px",
          }}
        >
          Logout
        </button>
      ) : (
        <>
          <Link to="/login">Login</Link>
          <Link to="/register">Register</Link>
        </>
      )}
    </nav>
  );
}

export default Navbar;
